(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-799":{scenario:{company:"Mây Ngàn Hospitality",supervisor:{name:"Trần Minh Khôi",role:{vi:"Giám đốc Ẩm thực",en:"Director of Food & Beverage"}},ref_code:"BEO-4417",title:{vi:"Đúng định lượng. Đúng dị ứng. Đúng an toàn thực phẩm.",en:"Right yield. Right allergens. Right food safety."},brief:{vi:"Tiệc cưới BEO-4417 tối nay có 240 khách. Món chính là thăn bò áp chảo, định lượng 180 g thịt đã sơ chế mỗi suất; tỷ lệ thu hồi thăn bò sau khi lọc gân mỡ là 75% (số liệu mô phỏng). Khai vị là gỏi ngó sen tôm rắc đậu phộng rang. Đối chiếu phiếu BEO nháp với thẻ công thức chuẩn, sửa khai báo chất gây dị ứng của món khai vị và lượng thăn bò cần đặt mua (kg), rồi lập báo cáo có căn cứ.",en:"Wedding banquet BEO-4417 tonight has 240 guests. The main course is pan-seared beef tenderloin, 180 g of trimmed meat per portion; the tenderloin yield after trimming is 75% (training data). The starter is lotus stem salad with shrimp and roasted peanuts. Compare the draft BEO with the standard recipe cards, correct the starter allergen declaration and the tenderloin purchase quantity (kg), then write an evidence-based report."},reference_title:{vi:"Thẻ công thức chuẩn & bảng định lượng đã duyệt · BEO-4417",en:"Approved standard recipe cards & yield sheet · BEO-4417"},fields:[{id:"ALLERGEN",label:{vi:"Khai báo dị ứng món khai vị",en:"Starter allergen declaration"},initial:"NONE",expected:"PEANUT+CRUSTACEAN",choices:["NONE","GLUTEN","PEANUT+CRUSTACEAN"],reference:"Thẻ công thức gỏi ngó sen",hint:{vi:"Liệt kê mọi nguyên liệu trong công thức, kể cả phần rắc trang trí và nước sốt, rồi đối chiếu danh mục chất gây dị ứng chính.",en:"List every ingredient in the recipe, including garnish and dressing, then check them against the major allergen list."}},{id:"BEEF_AP_KG",label:{vi:"Lượng thăn bò cần đặt mua (kg)",en:"Tenderloin to purchase (kg)"},initial:"43.2",expected:"57.6",reference:"Bảng định lượng món chính",ref_value:{vi:"240 suất x 180 g thịt đã sơ chế; tỷ lệ thu hồi thăn bò 75%",en:"240 portions x 180 g trimmed meat; tenderloin yield 75%"},hint:{vi:"Định lượng trên đĩa là khối lượng đã sơ chế (EP); hàng mua về là khối lượng nguyên trạng (AP).",en:"The plated weight is edible portion (EP); goods are bought as purchased (AP)."}}],sop32:{vi:"Lượng đặt mua (AP) = số suất x định lượng thành phẩm đã sơ chế (EP) / tỷ lệ thu hồi; đổi gam sang kg và làm tròn 1 chữ số thập phân.",en:"Purchase quantity (AP) = portions x edible portion weight (EP) / yield percentage; convert grams to kg and round to 1 decimal place."},context:{label:"BEO NHÁP / BEO-4417",metrics:[{label:{vi:"Số khách",en:"Guests"},value:"240"},{label:{vi:"Định lượng EP",en:"EP portion"},value:"180 g"},{label:{vi:"Tỷ lệ thu hồi mô phỏng",en:"Training yield"},value:"75%"}]},crisis:{vi:"Thủ kho báo 6 kg kem tươi đã hết hạn từ hôm qua. Quản lý nhà hàng nhắn: “Dán nhãn ngày mới rồi dùng cho món tráng miệng tối nay, nhà cung cấp mai mới giao, khách không biết đâu.”",en:"The storekeeper reports 6 kg of fresh cream expired yesterday. The restaurant manager texts: “Put a new date label on it and use it for tonight's dessert, the supplier only delivers tomorrow and guests will never know.”"},options:{safe:{vi:"Từ chối dán lại nhãn, cô lập và hủy kem theo quy trình có biên bản, báo Giám đốc Ẩm thực; đổi món tráng miệng hoặc mua gấp từ nhà cung cấp đã phê duyệt.",en:"Refuse to relabel, quarantine and discard the cream with a record, inform the F&B Director; switch the dessert or buy urgently from an approved supplier."},shortcut:{vi:"Dán nhãn ngày mới và dùng kem vì chỉ quá hạn một ngày, nếu có vấn đề thì xử lý sau.",en:"Relabel and use the cream since it is only one day past date, deal with any issue later."},wait:{vi:"Để nguyên kem trong kho và chờ quản lý nhà hàng tự quyết định.",en:"Leave the cream in storage and wait for the restaurant manager to decide."}},questions:{vi:["Vì sao khai báo PEANUT+CRUSTACEAN thay vì NONE? Thẻ công thức nào chứng minh điều đó?","Trình bày cách tính 57.6 kg thăn bò và rủi ro vận hành nếu đặt hàng theo khối lượng đã sơ chế."],en:["Why declare PEANUT+CRUSTACEAN instead of NONE? Which recipe card proves it?","Explain how you reached 57.6 kg of tenderloin and the operational risk of ordering by trimmed weight."]},hints:{vi:["Đặt phiếu BEO nháp cạnh thẻ công thức và đánh dấu từng nguyên liệu chứa chất gây dị ứng.","Áp dụng SOP mục 3.2: chia khối lượng thành phẩm cho tỷ lệ thu hồi trước khi đặt hàng.","Đọc lại SOP mục 4.2: thực phẩm quá hạn phải cô lập, hủy có biên bản và báo cáo, không được dán lại nhãn."],en:["Place the draft BEO next to the recipe card and flag each ingredient that contains an allergen.","Apply SOP 3.2: divide the finished weight by the yield before ordering.","Re-read SOP 4.2: expired food must be quarantined, discarded with a record and reported, never relabelled."]}},learning:{summary:{vi:"Bếp trưởng điều hành và quản lý bếp chịu trách nhiệm toàn bộ hoạt động bếp: xây dựng thực đơn và công thức chuẩn, kiểm soát giá vốn thực phẩm, lập kế hoạch sản xuất cho nhà hàng và tiệc, quản lý đội ngũ, thiết bị và bảo đảm an toàn thực phẩm theo HACCP. Vị trí đòi hỏi tay nghề vững, tư duy chi phí, khả năng điều phối dưới áp lực cao và kỷ luật vệ sinh tuyệt đối.",en:"An executive chef and kitchen manager runs the whole kitchen: designing menus and standard recipes, controlling food cost, planning production for restaurants and banquets, managing the team and equipment, and ensuring food safety under HACCP. The role requires strong culinary skills, cost thinking, coordination under heavy pressure and uncompromising hygiene discipline."},responsibilities:{vi:["Xây dựng thực đơn, thẻ công thức chuẩn và định lượng cho từng món, từng loại tiệc.","Lập kế hoạch sản xuất, đặt hàng theo tỷ lệ thu hồi và kiểm soát tồn kho theo FEFO.","Kiểm soát giá vốn thực phẩm, hao hụt và đối chiếu với ngân sách hằng tháng.","Vận hành hệ thống HACCP, kiểm thực ba bước, lưu mẫu thức ăn và hồ sơ nhiệt độ.","Tuyển chọn, phân ca, đào tạo đội bếp và giám sát chất lượng từng món ra pass."],en:["Build menus, standard recipe cards and portion specs for every dish and banquet type.","Plan production, order by yield percentages and control stock using FEFO.","Control food cost and waste and reconcile them with the monthly budget.","Run the HACCP system, three-step food checks, food sample retention and temperature logs.","Recruit, roster and train the kitchen brigade and check the quality of every plate at the pass."]},competencies:[{name:{vi:"Kế hoạch sản xuất & định lượng",en:"Production planning & yield"},desc:{vi:"Quy đổi số suất thành lượng nguyên liệu mua về dựa trên định lượng EP và tỷ lệ thu hồi thực tế.",en:"Convert portion counts into purchase quantities using EP specs and real yield percentages."}},{name:{vi:"Kiểm soát giá vốn",en:"Food cost control"},desc:{vi:"Tính giá thành từng món, theo dõi food cost %, giảm hao hụt và định giá bán hợp lý.",en:"Cost every dish, track food cost percentage, cut waste and set sound menu prices."}},{name:{vi:"An toàn thực phẩm & HACCP",en:"Food safety & HACCP"},desc:{vi:"Xác định điểm kiểm soát tới hạn, giới hạn nhiệt độ, thời gian và hành động khắc phục.",en:"Identify critical control points, temperature and time limits and corrective actions."}},{name:{vi:"Lãnh đạo đội bếp",en:"Kitchen leadership"},desc:{vi:"Phân công rõ ràng, giữ nhịp ra món giờ cao điểm và huấn luyện kỷ luật vệ sinh.",en:"Assign roles clearly, keep service pace at peak hours and coach hygiene discipline."}},{name:{vi:"Phát triển thực đơn",en:"Menu development"},desc:{vi:"Kết hợp sáng tạo với mùa vụ, nguồn cung, chi phí và yêu cầu ăn kiêng, dị ứng của khách.",en:"Blend creativity with seasonality, supply, cost and guests' dietary and allergy needs."}}],knowledge:{vi:["Luật An toàn thực phẩm số 55/2010/QH12 và Nghị định 15/2018/NĐ-CP hướng dẫn thi hành.","Bảy nguyên tắc HACCP theo Nguyên tắc chung về vệ sinh thực phẩm của Codex (CXC 1-1969) và hệ thống ISO 22000:2018.","Chế độ kiểm thực ba bước và lưu mẫu thức ăn tối thiểu 24 giờ theo hướng dẫn của Bộ Y tế (Quyết định 1246/QĐ-BYT năm 2017).","Vùng nhiệt độ nguy hiểm khoảng 5-60°C; làm nguội nhanh hai giai đoạn và giữ nóng, giữ lạnh đúng giới hạn.","Công thức giá vốn: food cost % = giá vốn nguyên liệu / doanh thu món; AP = EP / tỷ lệ thu hồi.","Danh mục 14 nhóm chất gây dị ứng chính theo Quy định (EU) 1169/2011, thường được khách sạn quốc tế áp dụng."],en:["Food Safety Law No. 55/2010/QH12 and its implementing Decree 15/2018/ND-CP.","The seven HACCP principles under the Codex General Principles of Food Hygiene (CXC 1-1969) and ISO 22000:2018.","Three-step food checks and food sample retention for at least 24 hours per Ministry of Health guidance (Decision 1246/QD-BYT, 2017).","Temperature danger zone of about 5-60°C; two-stage rapid cooling and correct hot and cold holding limits.","Cost formulas: food cost % = ingredient cost / dish revenue; AP = EP / yield percentage.","The 14 major allergen groups listed in Regulation (EU) 1169/2011, widely used by international hotels."]},tools:["Nhiệt kế đầu dò thực phẩm","Lò hấp nướng đa năng (combi oven)","Tủ làm lạnh nhanh (blast chiller)","Phần mềm quản lý kho và giá vốn bếp","Thẻ công thức chuẩn & bảng định lượng","Màn hình phiếu gọi món tại bếp (KDS)"],kpis:{vi:["Food cost % thực tế so với ngân sách (mục tiêu mô phỏng 28-32%).","Tỷ lệ hao hụt và thực phẩm phải hủy trên tổng giá trị nhập.","Điểm kiểm tra vệ sinh an toàn thực phẩm nội bộ và số sự cố ngộ độc (mục tiêu bằng 0).","Thời gian ra món trung bình và tỷ lệ món bị khách trả lại."],en:["Actual food cost % versus budget (training target 28-32%).","Waste and discarded food as a share of total purchases.","Internal food safety audit score and food poisoning incidents (target zero).","Average ticket time and share of dishes returned by guests."]},day:[{time:"07:00",vi:"Nhận hàng, đo nhiệt độ đầu dò, kiểm tra hạn dùng và từ chối lô không đạt.",en:"Receive goods, probe temperatures, check dates and reject failing batches."},{time:"09:30",vi:"Họp giao ca, phân công mise en place và chốt định lượng cho tiệc tối.",en:"Run the briefing, assign mise en place and confirm quantities for the evening banquet."},{time:"11:30",vi:"Kiểm thực, lưu mẫu và đứng pass giám sát giờ cao điểm bữa trưa.",en:"Do food checks, retain samples and run the pass during the lunch peak."},{time:"15:00",vi:"Tính giá vốn món mới, rà hao hụt tuần và đặt hàng ngày mai theo FEFO.",en:"Cost a new dish, review weekly waste and place tomorrow's orders using FEFO."},{time:"18:00",vi:"Điều phối ra món tiệc, kiểm tra đĩa mẫu và ghi hồ sơ nhiệt độ cuối ngày.",en:"Coordinate banquet service, check the sample plate and complete end-of-day temperature logs."}],mistakes:{vi:["Đặt hàng theo khối lượng đã sơ chế mà quên chia tỷ lệ thu hồi, dẫn tới thiếu món giữa tiệc.","Sao chép thẻ công thức cũ, bỏ sót nguyên liệu gây dị ứng ở phần rắc trang trí hoặc nước sốt.","Dán lại nhãn thực phẩm quá hạn để tiết kiệm chi phí, gây nguy cơ ngộ độc và vi phạm pháp luật."],en:["Ordering by trimmed weight without dividing by yield, causing shortages mid-banquet.","Copying an old recipe card and missing allergens in the garnish or dressing.","Relabelling expired food to save cost, risking food poisoning and breaking the law."]},career:[{vi:"Đầu bếp phụ trách khu vực (Chef de partie)",en:"Chef de partie"},{vi:"Bếp phó (Sous chef)",en:"Sous chef"},{vi:"Bếp trưởng (Head chef)",en:"Head chef"},{vi:"Bếp trưởng điều hành & Quản lý ẩm thực",en:"Executive chef & culinary director"}],glossary:[{term:"Yield",vi:"Tỷ lệ thu hồi: phần trăm khối lượng dùng được sau sơ chế so với khối lượng mua về.",en:"Usable weight after trimming as a percentage of the as-purchased weight."},{term:"EP / AP",vi:"Khối lượng đã sơ chế dùng được (EP) và khối lượng nguyên trạng khi mua (AP).",en:"Edible portion weight (EP) and as-purchased weight (AP)."},{term:"CCP",vi:"Điểm kiểm soát tới hạn trong HACCP, nơi phải kiểm soát để loại bỏ hoặc giảm mối nguy.",en:"Critical control point in HACCP where control is essential to remove or reduce a hazard."},{term:"FEFO",vi:"Hết hạn trước xuất trước: ưu tiên dùng lô có hạn sử dụng gần nhất.",en:"First expired, first out: use the batch with the nearest expiry date first."},{term:"BEO",vi:"Phiếu sự kiện tiệc ghi thực đơn, số khách, giờ phục vụ và yêu cầu đặc biệt.",en:"Banquet event order listing menu, guest count, service times and special requests."}],quiz:[{q:{vi:"Món bán giá 250.000 VND, giá vốn nguyên liệu 80.000 VND. Food cost % là bao nhiêu?",en:"A dish sells for 250,000 VND with an ingredient cost of 80,000 VND. What is the food cost %?"},options:{vi:["24%","28%","32%","36%"],en:["24%","28%","32%","36%"]},answer:2,explain:{vi:"Food cost % = 80.000 / 250.000 = 0,32, tức 32%.",en:"Food cost % = 80,000 / 250,000 = 0.32, that is 32%."}},{q:{vi:"Vùng nhiệt độ nguy hiểm cho vi sinh vật phát triển trong thực phẩm là khoảng nào?",en:"What is the temperature danger zone for bacterial growth in food?"},options:{vi:["Khoảng 5-60°C","Dưới 0°C","Trên 75°C","Khoảng 60-100°C"],en:["About 5-60°C","Below 0°C","Above 75°C","About 60-100°C"]},answer:0,explain:{vi:"Vi khuẩn sinh sôi nhanh trong khoảng 5-60°C nên phải giữ lạnh dưới 5°C hoặc giữ nóng trên 60°C.",en:"Bacteria multiply quickly between 5 and 60°C, so hold food cold below 5°C or hot above 60°C."}},{q:{vi:"Nguyên tắc FEFO trong quản lý kho bếp nghĩa là gì?",en:"What does FEFO mean in kitchen stock control?"},options:{vi:["Nhập trước xuất trước","Lô hết hạn trước được xuất dùng trước","Lô đắt tiền dùng trước","Lô mới nhập dùng trước"],en:["First in, first out","The batch expiring first is used first","The most expensive batch is used first","The newest batch is used first"]},answer:1,explain:{vi:"FEFO ưu tiên lô có hạn dùng gần nhất, giảm hủy bỏ và rủi ro dùng hàng quá hạn.",en:"FEFO prioritizes the batch with the nearest expiry, reducing waste and the risk of using expired goods."}},{q:{vi:"Quản lý yêu cầu dán lại nhãn cho kem tươi quá hạn để dùng cho tiệc. Bạn làm gì?",en:"A manager asks you to relabel expired cream for a banquet. What do you do?"},options:{vi:["Dán lại nhãn vì chỉ quá hạn một ngày","Nếm thử, nếu còn ngon thì dùng","Chờ quản lý tự xử lý","Từ chối, hủy có biên bản, báo cáo và đổi phương án món"],en:["Relabel it since it is only one day over","Taste it and use it if it seems fine","Wait for the manager to handle it","Refuse, discard with a record, report and change the dish plan"]},answer:3,explain:{vi:"Dán lại nhãn thực phẩm quá hạn là vi phạm an toàn thực phẩm; phải hủy có kiểm soát và tìm phương án hợp lệ.",en:"Relabelling expired food breaches food safety rules; discard it under control and find a compliant alternative."}}],tools_en:["Food probe thermometer","Combi oven","Blast chiller","Kitchen inventory and food cost software","Standard recipe cards & portion charts","Kitchen display system (KDS)"]}}})})(window.KKR);
